mapper.select:
SELECT id, tenant_id, workitem_id, conversation_id, turn_id, agent_id, executor_id, channel,
       provider, model, input_tokens, output_tokens, cache_read_tokens, cache_write_tokens,
       reasoning_tokens, credits, usage_at, gmt_create, gmt_modified
FROM agent_conversation_usage
WHERE tenant_id = #{tenantId}
  AND workitem_id = #{workitemId}
  AND channel = #{channel}
ORDER BY id
